raw_rows = props.get("stages") or []
if isinstance(raw_rows, str):
	try:
		raw_rows = json.loads(raw_rows)
	except Exception:
		raw_rows = [line for line in raw_rows.split("\n") if line.strip()]
if not isinstance(raw_rows, list):
	raw_rows = []
rows = []
for raw in raw_rows:
	try:
		parts = [part.strip() for part in str(raw).split("|")]
		while len(parts) < 7:
			parts.append("")
		if parts[0] or parts[1]:
			rows.append(parts)
	except Exception:
		continue

start = str(props.get("start") or "first").strip().lower()
ratios = ["5/4", "4/5", "4/5"]
stages = []
for parts in rows[:3]:
	index = len(stages)
	stages.append({
		"i": str(index),
		"name": parts[0],
		"when": parts[1],
		"src": parts[2],
		"alt": parts[3],
		"note": parts[4],
		"run": parts[5],
		"has_run": len(parts[5]) > 0,
		"focus": parts[6] or "50% 50%",
		"ratio": ratios[index],
	})
active = 0
if start == "last":
	active = max(len(stages) - 1, 0)
for i in range(len(stages)):
	on = i == active
	stages[i]["selected"] = "true" if on else "false"
	stages[i]["active"] = "true" if on else "false"
	stages[i]["tabindex"] = "0" if on else "-1"
component.stages = stages
component.stage = str(active)
component.count = str(max(len(stages), 1))
component.component_data = {"count": len(stages), "start_index": active}
